1	package agentusage
2	
3	import (
4		"errors"
5		"fmt"
6		"io"
7		"os"
8		"path/filepath"
9		"sort"
10		"strings"
11		"testing"
12	)
13	
14	func hasControl(s string) bool {
15		for _, r := range s {
16			if r < 0x20 || r == 0x7f {
17				return true
18			}
19		}
20		return false
21	}
22	
23	// --- 1. bounded memory ---
24	
25	func TestFilesCappedPerFileCountersKeepCounting(t *testing.T) {
26		dir := t.TempDir()
27		parent := filepath.Join(dir, sessUUID+".jsonl")
28		writeFile(t, parent, strings.Repeat("not json\n", 1000))
29		u, err := ParseSession(SessionFiles{ID: sessUUID, Parent: parent})
30		if err != nil {
31			t.Fatal(err)
32		}
33		d := u.Diagnostics
34		if d.UnreadableLines != 1000 || len(d.Files) != maxFileIssuesPerFile {
35			t.Fatalf("UnreadableLines=%d len(Files)=%d, want 1000 and %d", d.UnreadableLines, len(d.Files), maxFileIssuesPerFile)
36		}
37	}
38	
39	func TestFilesCapIsPerFile(t *testing.T) {
40		a := newAggregator([]Agent{{Main: true}})
41		for _, f := range []string{"a.jsonl", "b.jsonl"} {
42			for i := 0; i < 150; i++ {
43				a.addLine(0, f, int64(i*10), []byte("garbage"))
44			}
45		}
46		if a.diag.UnreadableLines != 300 || len(a.diag.Files) != 2*maxFileIssuesPerFile {
47			t.Fatalf("Unreadable=%d len(Files)=%d, want 300 and %d", a.diag.UnreadableLines, len(a.diag.Files), 2*maxFileIssuesPerFile)
48		}
49	}
50	
51	// Choice: past maxNoIDEntries, a line without message.id is still counted
52	// exactly once in NoMessageID, Messages and its tokens, but gets no
53	// per-message table entry (it can no longer be deduplicated; as no-id lines
54	// are keyed by offset they were never deduplicated anyway).
55	func TestNoIDEntriesCapped(t *testing.T) {
56		a := newAggregator([]Agent{{Main: true}})
57		const extra = 50
58		n := maxNoIDEntries + extra
59		for i := 0; i < n; i++ {
60			a.addLine(0, "p.jsonl", int64(i), msgLine("", "m", "end_turn", 1, 0, 0, 0))
61		}
62		if len(a.entries) > maxNoIDEntries {
63			t.Fatalf("entries = %d, want <= %d", len(a.entries), maxNoIDEntries)
64		}
65		got := a.finish()[0]
66		if a.diag.NoMessageID != n || got.Tokens.Input != int64(n) || got.Messages != n {
67			t.Fatalf("NoMessageID=%d input=%d messages=%d, want %d each", a.diag.NoMessageID, got.Tokens.Input, got.Messages, n)
68		}
69	}
70	
71	// --- 2. models and versions ---
72	
73	func TestModelsCappedFirstSeenFirst(t *testing.T) {
74		a := newAggregator([]Agent{{Main: true}})
75		for i := 0; i < 10000; i++ {
76			a.addLine(0, "p.jsonl", int64(i), msgLine(fmt.Sprintf("id%d", i), fmt.Sprintf("model-%d", i), "end_turn", 1, 0, 0, 0))
77		}
78		got := a.finish()[0]
79		if len(got.Models) != maxModelsPerAgent {
80			t.Fatalf("len(Models) = %d, want %d", len(got.Models), maxModelsPerAgent)
81		}
82		for i, m := range got.Models {
83			if m != fmt.Sprintf("model-%d", i) {
84				t.Fatalf("Models[%d] = %q, want first-seen order", i, m)
85			}
86		}
87		if got.Messages != 10000 {
88			t.Errorf("Messages = %d, want 10000", got.Messages)
89		}
90	}
91	
92	func TestLongModelTruncated(t *testing.T) {
93		long := strings.Repeat("m", 4000)
94		a := newAggregator([]Agent{{Main: true}})
95		a.addLine(0, "p.jsonl", 0, msgLine("i1", long, "end_turn", 1, 0, 0, 0))
96		got := a.finish()[0]
97		if len(got.Models) != 1 || got.Models[0] != long[:maxLabelLen] {
98			t.Fatalf("len(Models) = %d, want one entry of %d bytes", len(got.Models), maxLabelLen)
99		}
100	}
101	
102	func TestVersionsCappedAndTruncated(t *testing.T) {
103		a := newAggregator([]Agent{{Main: true}})
104		for i := 0; i < 500; i++ {
105			l := fmt.Sprintf(`{"version":"v%d","message":null}`, i)
106			a.addLine(0, "p.jsonl", int64(i), []byte(l))
107		}
108		a.noteVersion(strings.Repeat("v", 4000))
109		if v := a.versions(); len(v) != maxVersions || v[0] != "v0" {
110			t.Fatalf("len(versions) = %d (first %q), want %d", len(v), v[0], maxVersions)
111		}
112		b := newAggregator([]Agent{{Main: true}})
113		b.noteVersion(strings.Repeat("v", 4000))
114		if v := b.versions(); len(v) != 1 || len(v[0]) != maxLabelLen {
115			t.Fatalf("versions = %q, want one of %d bytes", v, maxLabelLen)
116		}
117	}
118	
119	// --- 3. sanitizing ---
120	// Choice: every control character (0x00-0x1f, 0x7f) becomes '?', then the
121	// label is truncated to maxLabelLen bytes.
122	
123	func TestSanitizeLabel(t *testing.T) {
124		for in, want := range map[string]string{
125			"plain":            "plain",
126			"a\x1b[31mb":       "a?[31mb",
127			"a\r\nb\x00c\x7fd": "a??b?c?d",
128			"":                 "",
129		} {
130			if got := sanitizeLabel(in); got != want {
131				t.Errorf("sanitizeLabel(%q) = %q, want %q", in, got, want)
132			}
133		}
134		if got := sanitizeLabel(strings.Repeat("x", 4000)); len(got) != maxLabelLen {
135			t.Errorf("len = %d, want %d", len(got), maxLabelLen)
136		}
137	}
138	
139	func TestDecodeLineSanitizesModelAndVersion(t *testing.T) {
140		line := `{"version":"2.1\u001b[2J\r\n","message":{"id":"i","model":"m\u001b]0;x\u0007\n","usage":{}}}`
141		r, kind := decodeLine([]byte(line))
142		if kind != kindUsage || hasControl(r.Model) || hasControl(r.Version) || r.Model == "" {
143			t.Fatalf("kind=%v model=%q version=%q: want sanitized", kind, r.Model, r.Version)
144		}
145	}
146	
147	func TestReadMetaSanitizesAgentType(t *testing.T) {
148		p := filepath.Join(t.TempDir(), "agent-x.meta.json")
149		writeFile(t, p, `{"agentType":"co\u001bder\n"}`)
150		m, err := readMeta(p)
151		if err != nil || hasControl(m.AgentType) || m.AgentType == "" {
152			t.Fatalf("AgentType = %q, err %v", m.AgentType, err)
153		}
154	}
155	
156	func TestControlCharactersInFileNamesNeverReachTheUsage(t *testing.T) {
157		proj := t.TempDir()
158		id := "ab\x1b[2Jcd\nef"
159		parent := filepath.Join(proj, id+".jsonl")
160		writeFile(t, parent, string(msgLine("m1", "x", "end_turn", 1, 1, 0, 0))+"\ngarbage\n"+`{"message":{"id":"p`)
161		sub := filepath.Join(proj, id, subagentsDir)
162		if err := os.MkdirAll(sub, 0o755); err != nil {
163			t.Skipf("filesystem refuses control characters in names: %v", err)
164		}
165		writeFile(t, filepath.Join(sub, "agent-s\x1b9\r.jsonl"), "garbage\n"+`{"message":{"id":"p`)
166		files, err := LocateSession(parent)
167		if err != nil {
168			t.Fatal(err)
169		}
170		u, err := ParseSession(files)
171		if err != nil {
172			t.Fatal(err)
173		}
174		all := []string{files.ID, u.SessionID}
175		for _, a := range u.Agents {
176			all = append(all, a.ID, a.Type)
177		}
178		for _, sa := range files.SubAgents {
179			all = append(all, sa.ID)
180		}
181		all = append(all, u.Diagnostics.TruncatedFiles...)
182		for _, f := range u.Diagnostics.Files {
183			all = append(all, f.File)
184		}
185		if len(u.Diagnostics.TruncatedFiles) == 0 || len(u.Diagnostics.Files) == 0 || len(u.Agents) != 2 {
186			t.Fatalf("setup produced no truncated/issue/sub-agent data: %+v", u)
187		}
188		for _, s := range all {
189			if hasControl(s) {
190				t.Errorf("label %q contains a control character", s)
191			}
192		}
193	}
194	
195	// --- 4. LocateSession ---
196	
197	func TestLocateSessionEmptyID(t *testing.T) {
198		p := filepath.Join(t.TempDir(), ".jsonl")
199		writeFile(t, p, "{}\n")
200		if _, err := LocateSession(p); err == nil {
201			t.Fatal("a parent named exactly .jsonl must be refused")
202		}
203	}
204	
205	func TestLocateSessionErrorsNeverCiteTheFullPath(t *testing.T) {
206		if os.Geteuid() == 0 {
207			t.Skip("permission errors cannot be provoked as root")
208		}
209		parent, dir := session(t)
210		if err := os.Mkdir(dir, 0o755); err != nil {
211			t.Fatal(err)
212		}
213		// sessionDir unreadable: Lstat of <dir>/subagents fails with EACCES.
214		if err := os.Chmod(dir, 0); err != nil {
215			t.Fatal(err)
216		}
217		t.Cleanup(func() { _ = os.Chmod(dir, 0o755) })
218		_, err := LocateSession(parent)
219		if err == nil || strings.Contains(err.Error(), filepath.Dir(parent)) {
220			t.Fatalf("err = %v, want an error naming only a base name", err)
221		}
222		// subagents unreadable: opening or reading it fails.
223		_ = os.Chmod(dir, 0o755)
224		sub := filepath.Join(dir, subagentsDir)
225		if err := os.Mkdir(sub, 0o755); err != nil {
226			t.Fatal(err)
227		}
228		if err := os.Chmod(sub, 0); err != nil {
229			t.Fatal(err)
230		}
231		t.Cleanup(func() { _ = os.Chmod(sub, 0o755) })
232		_, err = LocateSession(parent)
233		if err == nil || strings.Contains(err.Error(), filepath.Dir(parent)) {
234			t.Fatalf("err = %v, want an error naming only a base name", err)
235		}
236	}
237	
238	// --- 5. ParseSession on a non-regular parent ---
239	
240	func TestParseSessionNonRegularParentHasItsOwnError(t *testing.T) {
241		dir := t.TempDir()
242		real := filepath.Join(dir, "real.jsonl")
243		writeFile(t, real, "{}\n")
244		link := filepath.Join(dir, "link.jsonl")
245		if err := os.Symlink(real, link); err != nil {
246			t.Skip(err)
247		}
248		for name, p := range map[string]string{"symlink": link, "directory": dir} {
249			_, err := ParseSession(SessionFiles{Parent: p})
250			if err == nil || errors.Is(err, errNotPlain) || !errors.Is(err, errNotRegular) {
251				t.Errorf("%s: err = %v, want errNotRegular and not errNotPlain", name, err)
252			}
253		}
254	}
255	
256	// --- 6. record: model without id or usage ---
257	
258	func TestDecodeLineModelWithoutIDOrUsageIsNoUsage(t *testing.T) {
259		for name, tc := range map[string]struct {
260			line string
261			want lineKind
262		}{
263			"assistant model only": {`{"type":"assistant","version":"2.1.302","message":{"role":"assistant","model":"model-alpha","stop_reason":null,"content":[]}}`, kindNoUsage},
264			"user line":            {`{"type":"user","version":"2.1.302","message":{"role":"user","content":"hello"}}`, kindIgnored},
265			"tool_result":          {`{"type":"user","version":"2.1.302","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"t1","content":"ok"}]}}`, kindIgnored},
266		} {
267			if _, got := decodeLine([]byte(tc.line)); got != tc.want {
268				t.Errorf("%s: kind = %v, want %v", name, got, tc.want)
269			}
270		}
271	}
272	
273	// --- 7. mid-file read error ---
274	
275	type diskFailReader struct {
276		data string
277		pos  int
278	}
279	
280	func (f *diskFailReader) Read(p []byte) (int, error) {
281		if f.pos >= len(f.data) {
282			return 0, errors.New("disk on fire")
283		}
284		n := copy(p, f.data[f.pos:])
285		f.pos += n
286		return n, nil
287	}
288	
289	var _ io.Reader = (*diskFailReader)(nil)
290	
291	func TestParseReaderMidFileReadError(t *testing.T) {
292		l1 := string(msgLine("m1", "x", "end_turn", 3, 4, 0, 0)) + "\n"
293		l2 := string(msgLine("m2", "x", "end_turn", 5, 6, 0, 0)) + "\n"
294		a := newAggregator([]Agent{{Main: true}})
295		parseReader(a, 0, "p.jsonl", &diskFailReader{data: l1 + l2 + `{"message":{"id`})
296		got := a.finish()[0]
297		if got.Tokens.Input != 8 || got.Messages != 2 {
298			t.Fatalf("kept tokens=%+v messages=%d, want both complete lines", got.Tokens, got.Messages)
299		}
300		if a.diag.UnreadableLines != 0 {
301			t.Errorf("UnreadableLines = %d, want 0 (a read error is not an unreadable line)", a.diag.UnreadableLines)
302		}
303		want := FileIssue{File: "p.jsonl", Offset: int64(len(l1) + len(l2)), Kind: IssueReadError}
304		if len(a.diag.Files) != 1 || a.diag.Files[0] != want {
305			t.Fatalf("Files = %+v, want [%+v]", a.diag.Files, want)
306		}
307	}
308	
309	// --- 8. Files sorted by offset ---
310	
311	func TestFilesSortedByOffsetWithinAFile(t *testing.T) {
312		dir := t.TempDir()
313		parent := filepath.Join(dir, sessUUID+".jsonl")
314		big := strings.Repeat("x", MaxLineBytes+10)
315		writeFile(t, parent, "garbage\n"+big+"\ngarbage2\n"+big+"\ngarbage3\n")
316		u, err := ParseSession(SessionFiles{ID: sessUUID, Parent: parent})
317		if err != nil {
318			t.Fatal(err)
319		}
320		fs := u.Diagnostics.Files
321		if len(fs) != 5 || !sort.SliceIsSorted(fs, func(i, j int) bool { return fs[i].Offset < fs[j].Offset }) {
322			t.Fatalf("Files = %+v, want 5 entries by increasing Offset", fs)
323		}
324	}
325	
326	// --- 9. negative spawnDepth ---
327	
328	func TestReadMetaNegativeSpawnDepthIsZero(t *testing.T) {
329		p := filepath.Join(t.TempDir(), "agent-x.meta.json")
330		writeFile(t, p, `{"spawnDepth":-3}`)
331		m, err := readMeta(p)
332		if err != nil || m.SpawnDepth != 0 {
333			t.Fatalf("SpawnDepth = %d, err %v, want 0", m.SpawnDepth, err)
334		}
335	}
